/** User-specific Hub appearance, shared across Chat, Updates, Surveys and other tabs.
 * Built-in image inventory is generated by the FRONTEND build (not hard-coded here).
 * Personal image objects are private in Supabase and returned only as short-lived URLs.
 */
import { BadRequestException, ForbiddenException, Injectable, NotFoundException } from "@nestjs/common";
import type { AuthUser } from "../common/auth-user";
import { PrismaService } from "../prisma/prisma.service";
import { SupportStorageService, type SupportFile } from "./support-storage.service";

const BUILTIN = /^[a-zA-Z0-9][a-zA-Z0-9._-]{0,150}\.(?:png|jpg|jpeg|webp|gif|avif)$/i;
@Injectable()
export class SupportBackgroundsService {
  constructor(private readonly prisma: PrismaService, private readonly storage: SupportStorageService) {}

  private async identity(actor: AuthUser) {
    const accountId = String(actor?.accountId || "").trim(), userId = String(actor?.id || "").trim();
    if (!accountId || !userId) throw new ForbiddenException("Sign in first.");
    const valid = await this.prisma.userMembership.findFirst({
      where: { accountId, userId, active: true, status: "active" }, select: { id: true },
    });
    if (!valid) throw new ForbiddenException("Active membership required.");
    return { accountId, userId };
  }

  async list(actor: AuthUser) {
    const identity = await this.identity(actor);
    const [appearance, uploads] = await Promise.all([
      this.prisma.hubUserAppearance.findUnique({ where: { userId: identity.userId } }),
      this.prisma.hubBackgroundImage.findMany({ where: identity, orderBy: { createdAt: "desc" }, take: 100 }),
    ]);
    return { selected: { kind: appearance?.backgroundKind || "default", key: appearance?.backgroundKey || null },
      uploads: await Promise.all(uploads.map(async item => ({ id: item.id, name: item.name,
        sizeBytes: item.sizeBytes, mimeType: item.mimeType, createdAt: item.createdAt,
        url: await this.storage.backgroundUrl(item.storageKey) }))) };
  }

  async upload(actor: AuthUser, file?: SupportFile) {
    const identity = await this.identity(actor);
    const total = await this.prisma.hubBackgroundImage.count({ where: identity });
    if (total >= 100) throw new BadRequestException("Remove unused backgrounds before uploading more.");
    const stored = await this.storage.storeBackground(identity.accountId, identity.userId, file);
    try {
      const item = await this.prisma.hubBackgroundImage.create({ data: {
        ...identity, storageKey: stored.storageKey, name: stored.name,
        mimeType: stored.mimeType, sizeBytes: stored.sizeBytes,
      } });
      return { background: { id: item.id, name: item.name, mimeType: item.mimeType,
        sizeBytes: item.sizeBytes, url: await this.storage.backgroundUrl(item.storageKey) } };
    } catch (error) {
      await this.storage.remove(stored.storageKey).catch(() => undefined);
      throw error;
    }
  }

  async select(actor: AuthUser, body: Record<string, unknown>) {
    const identity = await this.identity(actor);
    const kind = String(body.kind || "default").trim();
    const key = String(body.key || "").trim();
    if (!["default", "builtin", "personal"].includes(kind)) throw new BadRequestException("Unknown background type.");
    if (kind === "builtin" && !BUILTIN.test(key)) throw new BadRequestException("Invalid bundled background name.");
    if (kind === "personal") {
      const item = await this.prisma.hubBackgroundImage.findFirst({ where: { ...identity, id: key } });
      if (!item) throw new NotFoundException("Uploaded background not found.");
    }
    const selected = await this.prisma.hubUserAppearance.upsert({
      where: { userId: identity.userId }, create: { ...identity,
        backgroundKind: kind, backgroundKey: kind === "default" ? null : key },
      update: { accountId: identity.accountId, backgroundKind: kind, backgroundKey: kind === "default" ? null : key },
    });
    return { selected: { kind: selected.backgroundKind, key: selected.backgroundKey } };
  }

  async remove(actor: AuthUser, id: string) {
    const identity = await this.identity(actor);
    const item = await this.prisma.hubBackgroundImage.findFirst({ where: { id, ...identity } });
    if (!item) throw new NotFoundException("Background not found.");
    await this.storage.remove(item.storageKey);
    await this.prisma.$transaction([
      this.prisma.hubBackgroundImage.delete({ where: { id: item.id } }),
      this.prisma.hubUserAppearance.updateMany({
        where: { userId: identity.userId, backgroundKind: "personal", backgroundKey: id },
        data: { backgroundKind: "default", backgroundKey: null },
      }),
    ]);
    return { removed: true };
  }
}
